"""Derive SkyyTrees/build_skyytrees_0.6.1.py from SkyyTrees 0.6.0 (build_skyytrees_0.6.0.py = the SET pin, itself GENERATED by
tools/trees_0_6_0_patch.py). Edit THIS patch, never the generated script. Every anchor is asserted once; at the end every change is undone on
a copy and compared with 0.6.0 (tools/soundpass_gen.Patch).
Run:
    python tools/trees_0_6_1_patch.py && python SkyyTrees/build_skyytrees_0.6.1.py && python SkyyTrees/test_skyytrees_0.6.1.py
The display rule lives in tools/trees_v3_data.py (V4_MODNAME_SUFFIX / v4_mod_name); 0.6.0 leaves it False, so the 0.6.0 build stays byte-identical.
"""
import os, sys

ROOT = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
sys.path.insert(0, os.path.join(ROOT, "tools"))
import soundpass_gen as G

NOTE = '''0.6.1 (2026-10-23) = MODIFIER NODES SAY "MODIFIER" (cosmetic). Skyy (2026-10-23, Trees > Class > Priest, panel title "Martyr's Grace: Power"):
  "id put modifier in the name so it says martyr's grace: power modifier". Every modifier-unlock node of the class trees (hook 'mod') is now
  named "<Ability>: <Modifier> Modifier" (e.g. "Martyr's Grace: Power Modifier") wherever the node name shows (panel title, map tooltip, result
  lines, Right-now lists - one name table UNAME). A name that already ends in "Modifier" is not doubled. Saved keys, effect ids, ranks, gates,
  costs and texts are unchanged. SAVED DATA: none. ROLLBACK to 0.6.0: alone (the names are the only change).
'''

P = G.Patch(os.path.join(ROOT, "SkyyTrees", "build_skyytrees_0.6.0.py"), os.path.join(ROOT, "SkyyTrees", "build_skyytrees_0.6.1.py"))
if "--out" in sys.argv:
    P.dst = os.path.abspath(sys.argv[sys.argv.index("--out") + 1])
assert P.has('VERSION = "0.6.0"') and not P.has("0.6.1 (2026-10-23)"), "not the generated SkyyTrees 0.6.0 script"
REG0, SYS0, CLS0 = P.s.count("registerCommand("), P.s.count("registerSystem("), P.s.count("makeClass(")

P.rep('''"""SkyyTrees 0.6.0 - build script (javassist via jpype, tools/skyybuild.py). Owner: Skyy (they/them).
GENERATED by tools/trees_0_6_0_patch.py from build_skyytrees_0.5.2.py (the SET pin) - edit the patch, not this file.
''', '''"""SkyyTrees 0.6.1 - build script (javassist via jpype, tools/skyybuild.py). Owner: Skyy (they/them).
GENERATED by tools/trees_0_6_1_patch.py from build_skyytrees_0.6.0.py (the SET pin) - edit the patch, not this file.
''' + NOTE + '''
SkyyTrees 0.6.0 - GENERATED by tools/trees_0_6_0_patch.py from build_skyytrees_0.5.2.py:
''')
P.rep('VERSION = "0.6.0"', 'VERSION = "0.6.1"')
P.rep('''V3D.v4_apply()               # 0.6.0: THE CLASS TREE REBUILD''', '''V3D.V4_MODNAME_SUFFIX = True   # 0.6.1: modifier unlock nodes are named "<Ability>: <Modifier> Modifier"
V3D.v4_apply()               # 0.6.0: THE CLASS TREE REBUILD''')
assert P.s.count("registerCommand(") == REG0 and P.s.count("registerSystem(") == SYS0
P.finish()
